package com.univmar.customer.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="customer") public class Customer { @Id private UUID id; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private CustomerType type; @Column(nullable=false,length=180) private String name; @Column(length=180) private String companyName; @Column(length=180) private String email; @Column(length=60) private String phone; @Column(columnDefinition="text") private String notes; @Column(nullable=false) private boolean active=true; @OneToMany(mappedBy="customer",cascade=CascadeType.ALL,orphanRemoval=true) private final List<CustomerContact> contacts=new ArrayList<>(); @OneToMany(mappedBy="customer",cascade=CascadeType.ALL,orphanRemoval=true) private final List<CustomerAddress> addresses=new ArrayList<>(); @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; protected Customer(){} public Customer(CustomerType type,String name,String companyName,String email,String phone,String notes){id=UUID.randomUUID();update(type,name,companyName,email,phone,notes);} public void update(CustomerType type,String name,String companyName,String email,String phone,String notes){this.type=type;this.name=name;this.companyName=companyName;this.email=email;this.phone=phone;this.notes=notes;} public void addContact(CustomerContact value){contacts.add(value);} public void addAddress(CustomerAddress value){addresses.add(value);} public void setActive(boolean active){this.active=active;} @PrePersist void addDates(){createdAt=updatedAt=Instant.now();}@PreUpdate void touch(){updatedAt=Instant.now();} public UUID getId(){return id;} public CustomerType getType(){return type;} public String getName(){return name;} public String getCompanyName(){return companyName;} public String getEmail(){return email;} public String getPhone(){return phone;} public String getNotes(){return notes;} public boolean isActive(){return active;} public List<CustomerContact> getContacts(){return List.copyOf(contacts);} public List<CustomerAddress> getAddresses(){return List.copyOf(addresses);} }
